Contract AutomatedTellerMachineSystem::printReceipt(): Real {

            precondition:
          InputCard.oclIsUndefined() = false and InputCard.CardStatus = BankCard::NORMAL and InputCard.Balance >= WithdrawedNumber

            postcondition:
          let receipt:BankCard in receipt.oclIsNew(), InputCard.Balance = InputCard.Balance - WithdrawedNumber, result = WithdrawedNumber

        }

Contract ManageSupplierCRUDService::createSupplier(id:Integer,name:String): Boolean {

            precondition:
          id <> null and name <> null and id > 0 and name.size() > 0 and Supplier.allInstance()->excludes(s | s.Id = id)

            postcondition:
          let s:Supplier in s.oclIsNew(), Supplier.allInstance()->includes(s), s.Id = id and s.Name = name, result = true

        }

Contract EnterValidatedCreditReferencesModule::markRequestValid(): Boolean {

            precondition:
          CurrentLoanRequest.oclIsUndefined() = false and CurrentLoanRequest.Status = 'SUBMITTED'

            postcondition:
          CurrentLoanRequest.Status = 'REFERENCESVALIDATED', CurrentLoanRequests->includes(CurrentLoanRequest)

        }

Contract GenerateLoanLetterAndAgreementModule::genereateApprovalLetter(id:Integer): Boolean {
          definition:
          req:LoanRequest = LoanRequest.allInstance()->any(r | r.RequestID = id)

            precondition:
          req.oclIsUndefined() = false and req.Status = 'SUBMITTED' and req.AttachedApprovalLetter = null

            postcondition:
          let letter:ApprovalLetter in letter.oclIsNew(), letter.Content = 'Approval Letter for Request ' + req.Name, req.AttachedApprovalLetter = letter, req.Status = 'REFERENCESVALIDATED', LoanRequest.allInstance()->includes(req)

        }
